// 1. Get the raw data from the node
const rawData = {{node:get_node_s2VhvFIi.data.data.payload}};

{{node:get_node_s2VhvFIi.data.data.payload}}

// 2. Parse the string into an actual array
// Expected format: '["201355...", "201356..."]'
const dataArray = JSON.parse(rawData);

// 3. Return the full list
// We verify it is an array to be safe; otherwise return empty list []
const ids = Array.isArray(dataArray) ? dataArray : [];

return {
  ids: ids
};

const source = {{node:search_node_WsApL9Dp.data.data}};
const materials = Array.isArray(source) ? source : (source ? [source] : []);
const sets = {
 categoryIds: new Set(), uomIds: new Set(), taxIds: new Set(), tariffIds: new Set(),
 customerIds: new Set(), supplierIds: new Set(), priceTagIds: new Set(), currencyIds: new Set()
};
const add = (key, value) => { if (value !== null && value !== undefined && value !== '') sets[key].add(String(value)); };
const activeRows = value => {
 let list = value;
 if (typeof list === 'string') { try { list = JSON.parse(list); } catch (error) { list = []; } }
 return (Array.isArray(list) ? list : []).filter(row => row && Number(row.is_deleted || 0) !== 1);
};
for (const item of materials) {
 add('categoryIds', item.item_category);
 for (const value of [item.based_uom, item.purchase_default_uom, item.sales_default_uom]) add('uomIds', value);
 for (const row of (Array.isArray(item.table_uom_conversion) ? item.table_uom_conversion : [])) {
  if (Number(row.is_deleted || 0) !== 1) add('uomIds', row.alt_uom_id);
 }
 for (const value of [item.mat_purchase_tax_id, item.mat_sales_tax_id]) add('taxIds', value);
 for (const value of [item.purchase_tariff_id, item.sales_tariff_id]) add('tariffIds', value);
 // Customer / supplier price rows: party, price tag, UOM and the currency selected on each row.
 for (const row of activeRows(item.table_customer_price)) {
  add('customerIds', row.customer_id);
  add('priceTagIds', row.cust_price_tag_id);
  add('uomIds', row.cust_price_uom);
  add('currencyIds', row.customer_currency);
 }
 for (const row of activeRows(item.table_supplier_price)) {
  add('supplierIds', row.supplier_id);
  add('priceTagIds', row.sup_price_tag_id);
  add('uomIds', row.sup_price_uom);
  add('currencyIds', row.supplier_currency);
 }
}
const result = {};
for (const [key, values] of Object.entries(sets)) {
 if (values.size > 100) throw new Error('Too many item references; select fewer items');
 result[key] = Array.from(values);
}
return result;

// 1.1 Currency org scope: task organization + its direct parent organization (if any).
// Mirrors the Item form currency selector (current org or parent org). Bigint IDs stay strings.
const text = v => {
  if (typeof v === 'number' && !Number.isSafeInteger(v)) throw new Error('Unsafe numeric organization ID; workflow must supply exact string IDs');
  return v == null ? '' : String(v).trim();
};
const taskOrg = text({{node:get_node_s2VhvFIi.data.data.organization_id}});
if (!taskOrg) throw new Error('Task organization is required');

const result = {{node:search_node_3niNLFdX.data}} || {};
const rows = Array.isArray(result) ? result : (Array.isArray(result.data) ? result.data : []);
const matches = rows.filter(row => text(row.id) === taskOrg && Number(row.is_deleted || 0) !== 1);
if (matches.length !== 1) throw new Error('Task organization not found or ambiguous');

const parentId = text(matches[0].parent_id);
const orgIds = [taskOrg];
if (parentId && parentId !== '0' && parentId !== taskOrg) orgIds.push(parentId);

return { orgIds };

// ATC_FETCH_POST_DATA: preserve UOM-specific values and omit missing optional settings.
const materials = rows({{node:search_node_WsApL9Dp.data.data}});
const categories = rows({{node:search_node_I842fXBz.data.data}});
const uoms = rows({{node:search_node_7CoKOOTf.data.data}});
const taxes = rows({{node:search_node_YpfNgNcX.data.data}});
const tariffs = rows({{node:search_node_pTaNRrbZ.data.data}});
// Price-row lookups (1.2 Price Customer / Supplier / Tag / Currency):
const priceCustomers = rows({{node:search_node_8gdiQHMK.data.data}});
const priceSuppliers = rows({{node:search_node_UYWUObf5.data.data}});
const priceTags = rows({{node:search_node_xwZAy3MX.data.data}});
const priceCurrencies = rows({{node:search_node_4eHECr11.data.data}});

function rows(value) {
  if (Array.isArray(value)) return value;
  if (value && Array.isArray(value.data)) return value.data;
  return value ? [value.data || value] : [];
}
const hasValue = value => value !== null && value !== undefined && value !== '';
const text = value => value == null ? '' : String(value);
const sanitize = value => text(value).replace(/"/g, '\u2033');
function numeric(value, field) {
  if (!hasValue(value)) return undefined;
  const n = Number(value);
  if (typeof value === 'boolean' || !text(value).trim() || !Number.isFinite(n)) throw new Error('Invalid ' + field);
  return n;
}
function flag(value, field) {
  if (!hasValue(value)) return undefined;
  if (value === true || value === 1 || value === '1') return true;
  if (value === false || value === 0 || value === '0') return false;
  throw new Error('Invalid ' + field);
}
function lookup(list, id, field, label) {
  if (!hasValue(id)) return undefined;
  const found = list.filter(row => text(row.id) === text(id) && Number(row.is_deleted || 0) !== 1);
  if (found.length !== 1 || !hasValue(found[0][field])) throw new Error('Unresolved or ambiguous ' + label);
  return text(found[0][field]);
}
function optional(target, key, value) { if (value !== undefined) target[key] = value; }
// ---- Customer / supplier price rows (currency is the code of the currency selected on each row) ----
// PROPOSED payload contract: field names must be agreed with the agent DTO before publishing.
function activePriceRows(value) {
  let list = value;
  if (typeof list === 'string') { try { list = JSON.parse(list); } catch (error) { throw new Error('Invalid price table'); } }
  return (Array.isArray(list) ? list : []).filter(row => row && Number(row.is_deleted || 0) !== 1);
}
function discountText(value, type) {
  const n = numeric(value, 'price discount');
  if (n === undefined) return undefined;
  return type === '%' ? text(n) + '%' : text(n);
}
function dateText(value) { return hasValue(value) ? text(value) : undefined; }
function resolvePriceRow(row, customerSide) {
  const partyId = customerSide ? row.customer_id : row.supplier_id;
  const tagId = customerSide ? row.cust_price_tag_id : row.sup_price_tag_id;
  const p = customerSide ? 'cust' : 'sup';
  const account = customerSide
    ? lookup(priceCustomers, partyId, 'customer_id', 'price-row customer')
    : lookup(priceSuppliers, partyId, 'supplier_code', 'price-row supplier');
  const tag = lookup(priceTags, tagId, 'price_tag_code', 'price tag');
  if (!account && !tag) throw new Error('Price row needs a customer/supplier or a price tag');
  const uom = lookup(uoms, row[p + '_price_uom'], 'uom_name', 'price-row UOM');
  if (!uom) throw new Error('Price-row UOM is required');
  // Exact currency of the row. Blank stays blank (never guessed or replaced by the party default).
  const currency = lookup(priceCurrencies, customerSide ? row.customer_currency : row.supplier_currency, 'currency_code', 'price-row currency');
  return {
    rowId: text(row.id), account, tag, uom, currency,
    minQty: numeric(row[p + '_min_order_qty'], 'minimum order quantity'),
    maxQty: numeric(row[p + '_max_order_qty'], 'maximum order quantity'),
    price: numeric(row[p + '_price_unit_price'], 'unit price'),
    discount: discountText(row[p + '_price_discount'], row[p + '_price_discount_type']),
    dateFrom: dateText(row[p + '_price_date_from']),
    dateTo: dateText(row[p + '_price_date_to'])
  };
}

function barcode(value) {
  if (!hasValue(value)) return undefined;
  if (typeof value !== 'string') throw new Error('Barcode must be text to preserve leading zeros');
  return value;
}

function prices(row) {
  const result = {};
  const map = {
    StandardCost: 'purchase_unit_price', SellingPrice: 'sales_unit_price',
    StandardSellingPrice2: 'sales_price_2', Price3: 'sales_price_3', Price4: 'sales_price_4',
    Price5: 'sales_price_5', Price6: 'sales_price_6', MinPurchasePrice: 'purchase_min_price',
    MaxPurchasePrice: 'purchase_max_price', MinSalePrice: 'sales_min_price', MaxSalePrice: 'sales_max_price', MinQty: 'min_purchase_qty'
  };
  for (const [native, saas] of Object.entries(map)) {
    const value = native === 'SellingPrice' && !hasValue(row?.[saas]) ? row?.sales_price_1 : row?.[saas];
    optional(result, native, numeric(value, native));
  }
  return result;
}

const postData = materials.map(material => {
  const base = lookup(uoms, material.based_uom, 'uom_name', 'base UOM');
  if (!base) throw new Error('Base UOM is required');
  const seen = new Set();
  const resolved = rows(material.table_uom_conversion).filter(row => Number(row.is_deleted || 0) !== 1).map(row => {
    const name = lookup(uoms, row.alt_uom_id, 'uom_name', 'item UOM');
    if (!name) throw new Error('Item UOM is required');
    const key = name.toUpperCase();
    if (seen.has(key)) throw new Error('Duplicate item UOM');
    seen.add(key);
    return { row, name };
  });
  const baseRow = resolved.find(line => line.name.toUpperCase() === base.toUpperCase())?.row;
  const baseValues = { ...prices(material), ...prices(baseRow) };
  const item = {
    id: text(material.id), AutoKey: text(material.item_uuid), ItemCode: sanitize(material.material_code),
    Description: sanitize(material.material_name), Description2: sanitize(material.material_desc),
    ItemGroup: sanitize(lookup(categories, material.item_category, 'mat_cat_code', 'item category') || ''),
    BaseUOM: base, IsActive: Number(material.is_active) === 1,
    BaseUomData: { ...baseValues }, AdditionalUOMs: []
  };
  // Keep legacy header cost/price compatible; always use BASE-UOM prices here.
  optional(item, 'StandardCost', baseValues.StandardCost);
  optional(item, 'SellingPrice', baseValues.SellingPrice);
  optional(item, 'StockControl', flag(material.stock_control, 'stock control'));
  if (hasValue(material.material_costing_method)) {
    const costing = { 'Fixed Cost': 0, 'Weighted Average': 1, 'First In First Out': 2 }[material.material_costing_method];
    if (costing === undefined) throw new Error('Unknown costing method');
    item.CostingMethod = costing;
  }
  optional(item, 'TaxCode', lookup(taxes, material.mat_sales_tax_id, 'tax_code', 'sales tax'));
  optional(item, 'PurchaseTaxCode', lookup(taxes, material.mat_purchase_tax_id, 'tax_code', 'purchase tax'));
  optional(item, 'TariffCode', lookup(tariffs, material.sales_tariff_id, 'tariff_code', 'sales tariff'));
  if (hasValue(material.irbm_id)) item.Classification = text(material.irbm_id);
  const baseBarcode = barcode(hasValue(baseRow?.item_barcode) ? baseRow.item_barcode : material.barcode_number);
  optional(item.BaseUomData, 'Barcode', baseBarcode);
  for (const { row, name } of resolved) {
    if (name.toUpperCase() === base.toUpperCase()) continue;
    const altQty = numeric(row.alt_qty, 'alternate quantity');
    const baseQty = numeric(row.base_qty, 'base quantity');
    if (!(altQty > 0) || !(baseQty > 0)) throw new Error('UOM conversion quantities must be positive');
    const line = { UOM: name, RATE: baseQty / altQty, ...prices(row) };
    optional(line, 'Barcode', barcode(row.item_barcode));
    item.AdditionalUOMs.push(line);
  }
  function defaultUom(field, legacy) {
    const selected = resolved.filter(line => flag(line.row[field], field) === true);
    if (selected.length > 1) throw new Error('Multiple ' + field + ' values');
    const name = selected.length ? selected[0].name : lookup(uoms, legacy, 'uom_name', field);
    if (name && name.toUpperCase() !== base.toUpperCase() && !resolved.some(line => line.name.toUpperCase() === name.toUpperCase())) throw new Error('Default UOM is not an item UOM');
    return name;
  }
  optional(item, 'PurchaseUOM', defaultUom('purchase_default_uom', material.purchase_default_uom));
  optional(item, 'SalesUOM', defaultUom('sales_default_uom', material.sales_default_uom));
  // Price rows. Omitted when empty so existing accounting price rows are not erased.
  function atcPriceLine(row, customerSide) {
    const r = resolvePriceRow(row, customerSide);
    const line = { SaasRowId: r.rowId, AccNo: r.account || '', PriceCategory: r.tag || '', UOM: r.uom };
    optional(line, 'CurrencyCode', r.currency);
    optional(line, 'MinQty', r.minQty);
    optional(line, 'MaxQty', r.maxQty);
    optional(line, 'Price', r.price);
    optional(line, 'Discount', r.discount);
    optional(line, 'DateFrom', r.dateFrom);
    optional(line, 'DateTo', r.dateTo);
    return line;
  }
  const customerPrices = activePriceRows(material.table_customer_price).map(row => atcPriceLine(row, true));
  const supplierPrices = activePriceRows(material.table_supplier_price).map(row => atcPriceLine(row, false));
  if (customerPrices.length) item.ItemCustomerPrice = customerPrices;
  if (supplierPrices.length) item.ItemSupplierPrice = supplierPrices;
  return item;
});
return { postData };

// 1. Get the raw data from the node
const rawData = {{node:get_node_s2VhvFIi.data.data.payload}};

// 2. Parse the string into an actual array
// Expected format: '["201355...", "201356..."]'
const dataArray = JSON.parse(rawData);

// 3. Return the full list
// We verify it is an array to be safe; otherwise return empty list []
const ids = Array.isArray(dataArray) ? dataArray : [];

return {
  ids: ids
};

// ============================================================================
// 1. ACCESS RAW SO DATA
// ============================================================================

let dataArray = {{node:search_node_5ZAYuKXx.data.data}} || [];
dataArray = Array.isArray(dataArray) ? dataArray : [dataArray];

// ============================================================================
// 2. COLLECT VALID ITEM IDS
// ============================================================================

const itemIds = [];

const hasValue = (value) => {
  return (
    value !== null &&
    value !== undefined &&
    String(value).trim() !== ""
  );
};

dataArray.forEach((order) => {
  if (!Array.isArray(order?.table_so)) return;

  order.table_so.forEach((line) => {
    if (line && hasValue(line.item_name)) {
      itemIds.push(line.item_name);
    }
  });
});

// ============================================================================
// 3. DEDUPLICATE IDS
// ============================================================================

const uniqueItemIds = itemIds.filter((value, index, array) => {
  const key = String(value);

  return (
    array.findIndex((item) => String(item) === key) === index
  );
});

// Preserve the existing output shape used by the Item search node.
return {
  item_names: uniqueItemIds.map((id) => ({
    item_id: id
  }))
};

// Fetch SO data safely
const rawData = {{node:search_node_5ZAYuKXx.data.data}} || [];
const dbSo = Array.isArray(rawData) ? rawData : (rawData ? [rawData] : []);

// Define reference tables for lookup with fallbacks
const dbTable = {
  customer: {{node:search_node_GAgLRMyG.data.data}} || [],
  uom: {{node:search_node_3ywclHB4.data.data}} || [],
  taxRate: {{node:search_node_gANJpuP2.data.data}} || [],
  item: {{node:search_node_WxiJR1aM.data.data}} || [],
  agent: {{node:search_node_HB57CYoF.data.data}} || [],
  paymentTerms: {{node:search_node_MZl5ap6e.data.data}} || [],
  location: {{node:search_node_uG1hQB1X.data.data}} || [],
  accountingIntegrateConfig: {{node:search_node_bTJq3kc9.data.data}} || [],
  itemBundle: {{node:search_node_vCHkEICe.data.data}} || []
};

const safeString = (value) => {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }

  try {
    return String(value);
  } catch (e) {
    console.error("Conversion error:", e);
    return "";
  }
};

const sanitizeString = (value) => {
  return safeString(value).replace(/"/g, "\u2033");
};

const safeParseFloat = (value, defaultValue = 0) => {
  if (value === null || value === undefined || value === "") {
    return defaultValue;
  }

  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : defaultValue;
};

const hasValue = (value) => {
  return (
    value !== null &&
    value !== undefined &&
    safeString(value).trim() !== ""
  );
};

const lineKey = (value) => {
  return safeString(value).trim();
};

const formatDate = (dateStr) => {
  const value = safeString(dateStr).trim();
  if (!value) return "";

  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return value;
  }

  const isoDateMatch = value.match(/^(\d{4}-\d{2}-\d{2})T.*$/);
  if (isoDateMatch) {
    return isoDateMatch[1];
  }

  try {
    const date = new Date(value);
    if (Number.isNaN(date.getTime())) return "";

    const yyyy = date.getFullYear();
    const mm = String(date.getMonth() + 1).padStart(2, "0");
    const dd = String(date.getDate()).padStart(2, "0");

    return `${yyyy}-${mm}-${dd}`;
  } catch (e) {
    console.error("Date formatting error:", e);
    return "";
  }
};

const findCorrespondingRecord = (input, inputType, dbName) => {
  if (
    input === null ||
    input === undefined ||
    input === ""
  ) {
    return null;
  }

  try {
    const collection = Array.isArray(dbTable[dbName])
      ? dbTable[dbName]
      : [];

    return (
      collection.find(
        (data) =>
          String(data?.[inputType]) === String(input)
      ) || null
    );
  } catch (e) {
    console.error("Lookup error:", e);
    return null;
  }
};

const findCorrespondingProperty = (
  input,
  inputType,
  dbName,
  propertyName
) => {
  const record = findCorrespondingRecord(
    input,
    inputType,
    dbName
  );

  return record
    ? safeString(record[propertyName])
    : "";
};

const deepSanitize = (data) => {
  if (Array.isArray(data)) {
    return data.map(deepSanitize);
  }

  if (data && typeof data === "object") {
    return Object.fromEntries(
      Object.entries(data).map(([key, value]) => [
        key,
        deepSanitize(value)
      ])
    );
  }

  if (
    typeof data === "number" ||
    typeof data === "boolean"
  ) {
    return data;
  }

  return sanitizeString(data);
};

const normalizeDiscount = (
  discountValue,
  discountUom
) => {
  const discount = safeString(
    discountValue
  ).trim();

  const uom = safeString(
    discountUom
  ).trim();

  if (!discount) return "";

  if (uom === "%") {
    return discount.endsWith("%")
      ? discount
      : `${discount}%`;
  }

  return discount;
};

// When enabled, AutoCount generates the Sales Order number.
const isSoGetAccNoEnabled = () => {
  const configs = Array.isArray(
    dbTable.accountingIntegrateConfig
  )
    ? dbTable.accountingIntegrateConfig
    : [dbTable.accountingIntegrateConfig];

  return configs.some((config) => {
    const value = config?.so_get_acc_no;

    return (
      value === true ||
      value === 1 ||
      value === "1"
    );
  });
};

const mapDetailLine = (item) => {
  return {
    ItemCode: findCorrespondingProperty(
      item?.item_name,
      "id",
      "item",
      "material_code"
    ),

    UOM: findCorrespondingProperty(
      item?.so_item_uom,
      "id",
      "uom",
      "uom_name"
    ),

    Qty: safeParseFloat(
      item?.so_quantity
    ),

    Discount: normalizeDiscount(
      item?.so_discount,
      item?.so_discount_uom
    ),

    Description: findCorrespondingProperty(
      item?.item_name,
      "id",
      "item",
      "material_name"
    ),

    Desc2: sanitizeString(
      item?.so_desc || ""
    ),

    FurtherDescription: sanitizeString(
      item?.more_desc || ""
    ),

    TaxCode: findCorrespondingProperty(
      item?.so_tax_preference,
      "id",
      "taxRate",
      "tax_code"
    ),

    TaxRate: safeParseFloat(
      item?.so_tax_percentage
    ),

    Location: findCorrespondingProperty(
      item?.plant_id,
      "id",
      "location",
      "dept_name"
    ),

    UnitPrice: safeParseFloat(
      item?.so_item_price
    ),

    DeliveryDate: formatDate(
      item?.so_shipping_date
    )
  };
};

const isBundleMasterLine = (line) => {
  return (
    !!line &&
    !hasValue(line.parent_id) &&
    hasValue(line.item_bundle_id)
  );
};

const isValidPackageDetail = (line) => {
  if (!line || !line.ItemCode) {
    return false;
  }

  if (
    !Number.isFinite(line.Qty) ||
    line.Qty === 0
  ) {
    return false;
  }

  if (!Number.isFinite(line.UnitPrice)) {
    return false;
  }

  return true;
};

const resolvePackageCode = (item) => {
  // The SO bundle master normally supplies PackageCode in item_id.
  const suppliedCode = sanitizeString(
    item?.item_id || ""
  ).trim();

  if (suppliedCode) {
    return suppliedCode;
  }

  // Fall back to the Item Bundle lookup when item_id is empty.
  return sanitizeString(
    findCorrespondingProperty(
      item?.item_bundle_id,
      "id",
      "itemBundle",
      "ib_no"
    )
  ).trim();
};

const mapPackageLine = (
  item,
  allLines
) => {
  const packageCode = resolvePackageCode(item);
  const parentId = lineKey(item?.id);

  const packageDetails = allLines
    .filter(
      (line) =>
        hasValue(line?.parent_id) &&
        lineKey(line.parent_id) === parentId
    )
    .map(mapDetailLine)
    .filter(isValidPackageDetail);

  if (!packageCode) {
    console.warn(
      `Skipping SO bundle parent ` +
      `${parentId || "(missing id)"}: ` +
      "PackageCode is empty."
    );

    return null;
  }

  if (packageDetails.length === 0) {
    console.warn(
      `Skipping SO bundle ${packageCode}: ` +
      "no valid package children were found."
    );

    return null;
  }

  const qty = safeParseFloat(
    item?.so_quantity
  );

  const unitPrice = safeParseFloat(
    item?.so_item_price
  );

  if (
    !Number.isFinite(qty) ||
    qty === 0
  ) {
    console.warn(
      `Skipping SO bundle ${packageCode}: ` +
      "master Qty is zero or invalid."
    );

    return null;
  }

  return {
    PackageCode: packageCode,

    UOM: findCorrespondingProperty(
      item?.so_item_uom,
      "id",
      "uom",
      "uom_name"
    ),

    Qty: qty,

    Discount: normalizeDiscount(
      item?.so_discount,
      item?.so_discount_uom
    ),

    Description: sanitizeString(
      item?.so_desc ||
      item?.item_id ||
      ""
    ),

    FurtherDescription: sanitizeString(
      item?.further_description ||
      item?.more_desc ||
      ""
    ),

    TaxCode: findCorrespondingProperty(
      item?.so_tax_preference,
      "id",
      "taxRate",
      "tax_code"
    ),

    TaxRate: safeParseFloat(
      item?.so_tax_percentage
    ),

    Location: findCorrespondingProperty(
      item?.plant_id,
      "id",
      "location",
      "dept_name"
    ),

    // The payload bundle-master price remains authoritative.
    UnitPrice: unitPrice,

    DeliveryDate: formatDate(
      item?.so_shipping_date
    ),

    PackageDetails: packageDetails
  };
};

const mapSalesOrderDetailLines = (
  lineItems
) => {
  // Only rows without parent_id may appear at the document level.
  const topLevelLines = lineItems.filter(
    (line) => !hasValue(line?.parent_id)
  );

  const bundleParentIds = new Set(
    topLevelLines
      .filter(isBundleMasterLine)
      .map((line) => lineKey(line?.id))
      .filter(Boolean)
  );

  // Child rows must only appear inside PackageDetails.
  lineItems.forEach((line) => {
    if (
      hasValue(line?.parent_id) &&
      !bundleParentIds.has(
        lineKey(line.parent_id)
      )
    ) {
      console.warn(
        `Skipping orphan SO child ` +
        `${lineKey(line?.id) || "(missing id)"}: ` +
        `bundle parent ` +
        `${lineKey(line?.parent_id)} ` +
        "was not found."
      );
    }
  });

  return topLevelLines
    .map((line) => {
      if (isBundleMasterLine(line)) {
        return mapPackageLine(
          line,
          lineItems
        );
      }

      return mapDetailLine(line);
    })
    .filter((line) => line !== null);
};

