const safeString = (value) => {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean") {
    return String(value);
  }

  try {
    return String(value);
  } catch (e) {
    console.error("Conversion error:", e);
    return "";
  }
};

const sanitizeString = (value) => {
  return safeString(value).replace(/"/g, "\u2033");
};

const safeParseFloat = (value, defaultValue = 0) => {
  if (value === null || value === undefined || value === "") {
    return defaultValue;
  }

  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : defaultValue;
};

const hasValue = (value) => {
  return (
    value !== null &&
    value !== undefined &&
    safeString(value).trim() !== ""
  );
};

const lineKey = (value) => safeString(value).trim();

const formatDate = (dateStr) => {
  const value = safeString(dateStr).trim();

  if (!value) return "";

  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return value;
  }

  const isoDateMatch = value.match(/^(\d{4}-\d{2}-\d{2})T.*$/);

  if (isoDateMatch) {
    return isoDateMatch[1];
  }

  try {
    const date = new Date(value);

    if (Number.isNaN(date.getTime())) {
      return "";
    }

    const yyyy = date.getFullYear();
    const mm = String(date.getMonth() + 1).padStart(2, "0");
    const dd = String(date.getDate()).padStart(2, "0");

    return `${yyyy}-${mm}-${dd}`;
  } catch (e) {
    console.error("Date formatting error:", e);
    return "";
  }
};

const formatValidityPeriod = (value) => {
  if (!value) return "";

  if (Array.isArray(value)) {
    const startDate = formatDate(value[0]);
    const endDate = formatDate(value[1]);

    if (startDate && endDate) {
      return `${startDate} - ${endDate}`;
    }

    if (startDate) return startDate;
    if (endDate) return endDate;

    return "";
  }

  return sanitizeString(value);
};

const findCorrespondingRecord = (input, inputType, dbName) => {
  if (input === null || input === undefined || input === "") {
    return null;
  }

  try {
    const collection = Array.isArray(dbTable[dbName])
      ? dbTable[dbName]
      : [];

    return (
      collection.find(
        (data) => String(data?.[inputType]) === String(input)
      ) || null
    );
  } catch (e) {
    console.error("Lookup error:", e);
    return null;
  }
};

const findCorrespondingProperty = (
  input,
  inputType,
  dbName,
  propertyName
) => {
  const record = findCorrespondingRecord(input, inputType, dbName);

  return record ? safeString(record[propertyName]) : "";
};

const deepSanitize = (data) => {
  if (Array.isArray(data)) {
    return data.map(deepSanitize);
  }

  if (data && typeof data === "object") {
    return Object.fromEntries(
      Object.entries(data).map(([key, value]) => [
        key,
        deepSanitize(value)
      ])
    );
  }

  if (typeof data === "number" || typeof data === "boolean") {
    return data;
  }

  return sanitizeString(data);
};

const normalizeDiscount = (value, discountUomId) => {
  if (value === null || value === undefined || value === "") {
